function parseAliases(s: string): string[] {
  return s.split(",").map((x) => x.trim()).filter(Boolean);
}

export const CATALOG: TopicMeta[] = ROWS.map((r) => ({
  id: r[0],
  category: r[1],
  slug: r[2],
  titleUk: r[3],
  titlePt: r[4],
  titleEn: r[5],
  summary: r[6],
  aliases: parseAliases(r[7]),
  related: parseAliases(r[8]),
  depth: r[9],
}));

export const TOPIC_BY_ID = new Map(CATALOG.map((t) => [t.id, t]));

export const TOPIC_BY_PATH = new Map(
  CATALOG.map((t) => [`${t.category}/${t.slug}`, t]),
);

export function topicsInCategory(category: string): TopicMeta[] {
  return CATALOG.filter((t) => t.category === category);
}

export function topicHref(t: Pick<TopicMeta, "category" | "slug">): string {
  if (t.category === "comparisons") return `/comparisons/${t.slug}`;
  if (t.category === "regional") return `/regional/${t.slug}`;
  return `/pt/${t.category}/${t.slug}`;
}

